create function admin_action_append_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (select from pg_locks
             where locktype = 'advisory' and pid = pg_backend_pid() and granted
               and classid = 0 and objid = 20261110 and objsubid = 1) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;
  raise exception 'admin_action is append-only: % refused', tg_op;
end
$$
